import React, { useState } from 'react';
import './App.css';
import { processLogFile } from './services/parser';

function App() {
  const [auditData, setAuditData] = useState(null);
  const [error, setError] = useState(null);

  const handleFileUpload = async (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const text = await file.text();
    const result = processLogFile(text);

    if ('error' in result) {
      setError(result.error);
      setAuditData(null);
    } else {
      setError(null);
      setAuditData(result.runs);
    }
  };

  return (
    <div className="App">
      <header className="App-header">
        <h1>🧾 Audit Log Viewer</h1>
        <input type="file" accept=".csv" onChange={handleFileUpload} />
        {error && <p style={{ color: 'salmon', marginTop: '20px' }}>⚠️ Error: {error}</p>}

        {auditData && (
          <table style={{ marginTop: '20px', borderCollapse: 'collapse', width: '90%', maxWidth: '900px' }}>
            <thead>
              <tr>
                <th style={{ borderBottom: '1px solid #ccc', padding: '8px' }}>Unique Key</th>
                <th style={{ borderBottom: '1px solid #ccc', padding: '8px' }}>Company Code</th>
                <th style={{ borderBottom: '1px solid #ccc', padding: '8px' }}>Request Types</th>
                <th style={{ borderBottom: '1px solid #ccc', padding: '8px' }}>Flags</th>
              </tr>
            </thead>
            <tbody>
              {auditData.map((run) => (
                <tr key={run.uniqueKey}>
                  <td style={{ padding: '8px' }}>{run.uniqueKey}</td>
                  <td style={{ padding: '8px' }}>{run.companyCode || 'N/A'}</td>
                  <td style={{ padding: '8px' }}>{run.requestTypes.join(', ')}</td>
                  <td style={{ padding: '8px' }}>
                    {[
                      run.isIntercompany && 'Intercompany',
                      run.isAutoApproved && 'Auto-approved',
                      run.isSecondLevelApproval && '2nd-level',
                      run.isErrorTransaction && 'Error',
                      run.isWbsOwnerMissing && 'WBS missing',
                      run.isCostCenterOwnerMissing && 'Cost Center missing',
                      run.isFallbackTransaction && 'Fallback',
                    ]
                      .filter(Boolean)
                      .join(', ')}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </header>
    </div>
  );
}

export default App;
